WHERE sr.deleted = 0

  AND (sr.record_no LIKE CONCAT('%', #{keyword}, '%')
    OR sr.platform_order_no LIKE CONCAT('%', #{keyword}, '%')
    OR sr.buyer_name LIKE CONCAT('%', #{keyword}, '%')
    OR p.product_name LIKE CONCAT('%', #{keyword}, '%')
    OR pu.purchase_no LIKE CONCAT('%', #{keyword}, '%'))


  AND sr.payment_status = #{paymentStatus}


  AND sr.shipment_status = #{shipmentStatus}


  AND sr.business_date >= #{startDate}


  AND sr.business_date <= #{endDate}
